<?php require_once __DIR__.'/config/database.php';require_once __DIR__.'/config/session.php';requireLogin();$uid=$_SESSION['user_id'];$s=$conn->prepare('SELECT * FROM stress_assessments WHERE user_id=? ORDER BY created_at DESC');$s->bind_param('i',$uid);$s->execute();$r=$s->get_result();?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Report</title><link rel="stylesheet" href="assets/css/style.css"></head><body><main class="container"><div class="title"><h2>StressCare Report</h2></div><div class="card table-wrap"><table><tr><th>Date</th><th>Stress</th><th>Emotion</th><th>Concern</th><th>Sleep</th></tr><?php while($x=$r->fetch_assoc()):?><tr><td><?=date('d M Y',strtotime($x['created_at']))?></td><td><?=$x['stress_level']?>/10</td><td><?=htmlspecialchars($x['emotion']?:$x['mood'])?></td><td><?=htmlspecialchars($x['situation']?:'General Stress')?></td><td><?=$x['sleep_hours']?> hrs</td></tr><?php endwhile;?></table></div></main></body></html>
